def half(n: int) -> float:
    return n / 2


def avg(a: int, b: int) -> float:
    return (a + b) / 2


print(half(7))
print(half(7) + 1)
print(avg(3, 4))
print(avg(3, 4) + 10)
print(half(10) > 4)
